head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf00008";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $("input[name=integ_usr_id]").focus().select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00008.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_SendForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf00008.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_integUsrId_onpaste
 * @description ipt_integUsrId onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_integUsrId_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00008.ipt_integUsrId_onpaste' }); }
};

/**
 * @method
 * @name ipt_isurCd_onpaste
 * @description ipt_isurCd onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isurCd_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00008.ipt_isurCd_onpaste' }); }
};

/**
 * @method
 * @name ipt_chrgNm_onblur
 * @description ipt_chrgNm 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_chrgNm_onblur = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.chk_chrg_nm(selfVar, 20, '이름');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf00008.ipt_chrgNm_onblur' }); }
};

/**
 * @method
 * @name ipt_chrgNm_onkeypress
 * @description ipt_chrgNm onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chrgNm_onkeypress = function(e){
    try {
        fn_etcNumNotCheck()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00008.ipt_chrgNm_onkeypress' }); }
};

/**
 * @method
 * @name ipt_chrgNm_onpaste
 * @description ipt_chrgNm onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chrgNm_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00008.ipt_chrgNm_onpaste' }); }
};

/**
 * @method
 * @name ipt_encrypChrgEmail1_onkeydown
 * @description ipt_encrypChrgEmail1 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_encrypChrgEmail1_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00008.ipt_encrypChrgEmail1_onkeydown' }); }
};

/**
 * @method
 * @name ipt_encrypChrgEmail2_onkeydown
 * @description ipt_encrypChrgEmail2 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_encrypChrgEmail2_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00008.ipt_encrypChrgEmail2_onkeydown' }); }
};

/**
 * @method
 * @name btn_requestPwChg_onclick
 * @description btn_requestPwChg 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_requestPwChg_onclick = async function(e){
    try {
        await scwin.requestPwChg()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf00008.btn_requestPwChg_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00008.btn_self_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name requestPwChg
 * @description request Pw Chg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.requestPwChg = async function () {
    if (!await scwin.chkData()) {
        return;
    }
    $c.util.getComponent("ipt_encrypChrgEmail").setValue($c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypChrgEmail2').getValue());
    const base_url = "";
    let action_path = "";
    action_path = "/corp/register.do?method=requestPwChg";
    scwin.form_SendForm.action = base_url + action_path;
    scwin.form_SendForm.target = "_self";
    await moveUrl(base_url + action_path, {});
};

/**
 * @method
 * @name chkData
 * @description chk Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkData = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_integUsrId').getValue().replace(/ /gi, "")) === 0) {
        await $c.win.alert("아이디를 입력하십시오.");
        $c.util.getComponent("ipt_integUsrId").setValue("");
        $c.util.getComponent("ipt_integUsrId").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_isurCd').getValue()) === 0) {
            await $c.win.alert("발행기관코드를 입력하십시오.");
            $c.util.getComponent("ipt_isurCd").focus();
            return false;
        } else {
            if ($c.util.getComponent('ipt_isurCd').getValue().replace(/ /gi, "").length < 5) {
                await $c.win.alert("발행기관코드 5자리를 입력하십시오.");
                $c.util.getComponent("ipt_isurCd").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_chrgNm').getValue()) === 0) {
                    await $c.win.alert("담당자 이름을 입력하십시오.");
                    $c.util.getComponent("ipt_chrgNm").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue()) === 0) {
                        await $c.win.alert("이메일을 입력하십시오.");
                        $c.util.getComponent("ipt_encrypChrgEmail1").focus();
                        return false;
                    } else {
                        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue()) === 0) {
                            await $c.win.alert("이메일을 입력하십시오.");
                            $c.util.getComponent("ipt_encrypChrgEmail2").focus();
                            return false;
                        } else {
                            if (!$c.str.isEmail($c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypChrgEmail2').getValue())) {
                                await $c.win.alert("이메일이 올바르지 않습니다.");
                                $c.util.getComponent("ipt_encrypChrgEmail2").focus();
                                return false;
                            }
                        }
                    }
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name chk_chrg_nm
 * @description chk chrg nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_chrg_nm = async function (fm) {
    const len = $c.str.getByteLength($c.util.getComponent('ipt_chrgNm').getValue());
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        $c.util.getComponent("ipt_chrgNm").focus();
        return;
    }
};
